<template>
  <view :class="['app-page', 'detail-page', { dark }]">
    <ui-header title="商品详情" back />
    <template v-if="product">
    <image class="main-image" :src="product.image" mode="aspectFill" />
    <view class="card product-main"><text class="product-name">{{ product.name }}</text><text class="product-sub">{{ product.subtitle || product.detailText }}</text><view class="price-line"><view><text class="price big">¥{{ product.price.toFixed(2) }}</text></view><view class="actions"><view @tap="showShare=true"><ui-icon name="share" :size="30"/><text>分享</text></view><view :class="{fav:isFav}" @tap="toggleFav"><ui-icon name="heart" :size="30" :tone="isFav?'primary':'muted'"/><text>{{ isFav?'已收藏':'收藏' }}</text></view></view></view></view>
    <view class="card spec-row" @tap="showSpec=true"><view><text class="section-title">商品规格</text><text class="spec-text">{{ selectedSku.name }}</text></view><ui-icon name="chevron-right" :size="34"/></view>
    <view class="card details"><text class="section-title">负责打手：{{product.playerName||'待平台配置'}}</text><text>平台统一收款与售后，服务由商品绑定的打手提供。</text></view>
    <view class="card details"><text class="section-title">详情</text><text>{{product.detailText||'服务内容以所选规格和订单约定为准。'}}</text><text>• 服务开始前可联系客服修改信息</text><text>• 服务完成后可在订单中心评价</text><text class="warning">所有服务均为陪玩体验，不涉及游戏代练。</text></view>
    <view class="card"><view class="review-head"><text class="section-title">评价（{{Number(product.reviewCount||0)}}）</text><text class="muted">好评度{{Number(product.goodRate||0)}}% · {{Number(product.averageRating||0).toFixed(1)}}分</text></view><view v-if="product.reviews&&product.reviews.length" class="review-list"><view v-for="review in product.reviews" :key="review.id" class="review-item"><view><text>{{review.nickname||'用户'}}</text><text class="review-rating">{{review.rating}}分</text></view><text>{{review.content||'用户未填写文字评价'}}</text><text class="muted">{{displayDateTime(review.createdAt)}}</text></view></view><view v-else class="review-empty"><ui-empty title="暂无更多评论" /></view></view>
    <view class="buybar"><view class="store" @tap="goStore"><ui-icon name="home" :size="38"/><text class="store-label">平台首页</text></view><view class="primary-btn buy" @tap="showSpec=true">立即购买</view></view>

    <view v-if="showSpec" class="sheet-mask" @tap="showSpec=false"><view class="sheet" @tap.stop><view class="sheet-top"><image :src="product.image" mode="aspectFill"/><view><text class="price">¥{{ total.toFixed(2) }}</text><text class="muted">已选：{{ selectedSku.name }}</text></view><view class="close" @tap="showSpec=false"><ui-icon name="x" :size="36"/></view></view><text class="section-title">选择规格</text><view class="sku-list"><view v-for="sku in product.skus" :key="sku.id" :class="['sku',{active:selectedSku.id===sku.id}]" @tap="selectedSku=sku">{{ sku.name }}　¥{{ sku.price.toFixed(2) }}</view></view><view class="qty"><text class="section-title">数量</text><view class="counter"><view @tap="qty=Math.max(1,qty-1)"><ui-icon name="minus" :size="28"/></view><text>{{ qty }}</text><view @tap="increaseQty"><ui-icon name="plus" :size="28"/></view></view></view><view class="primary-btn" @tap="submit">立即购买</view></view></view>
    <view v-if="showShare" class="sheet-mask" @tap="showShare=false"><view class="share-sheet" @tap.stop><view class="share-item" @tap="generatePoster"><view class="share-icon blue"><ui-icon name="image" :size="42" tone="white"/></view><text>生成海报</text></view><button class="share-item share-button" open-type="share"><view class="share-icon green"><ui-icon name="users" :size="42" tone="white"/></view><text>分享好友</text></button><view class="cancel" @tap="showShare=false">取消</view></view></view>
    </template>
    <ui-page-status v-else :loading="loading" :description="loadError" @retry="loadProduct" />
  </view>
</template>
<script>
import { api } from '@/services/api'; import { isDark } from '@/utils/app'
export default {
  data(){return{dark:false,productId:'1',product:null,loading:true,loadError:'请检查网络后重新加载',selectedSku:{name:'请选择',price:0},qty:1,showSpec:false,showShare:false,posterBusy:false,isFav:false,isFollow:false}},
  computed:{total(){return this.selectedSku.price*this.qty}},
  onLoad(q){this.dark=isDark();let scene='';try{scene=decodeURIComponent(q.scene||'')}catch{};this.productId=q.id||(scene.match(/(?:^|&)p=(\d+)/)||[])[1]||'1';this.loadProduct()},
  onShareAppMessage(){if(!this.product)return{title:'品奢电竞',path:'/pages/index/index'};return{title:this.product.name,path:'/pages/product/detail?id='+this.product.id,imageUrl:this.product.image}},
  methods:{
    loadProduct(){this.loading=true;this.loadError='请检查网络后重新加载';api.getProduct(this.productId).then(async item=>{if(!item)throw new Error('empty');this.product=item;this.selectedSku=item.skus[0];if(uni.getStorageSync('token')){const state=await api.getRelationState(item.id);this.isFav=state.favorite;this.isFollow=state.followed}}).catch(e=>{this.product=null;this.loadError=e.message||'商品信息暂时无法加载'}).finally(()=>{this.loading=false})},
    async toggleFav(){const state=await api.setFavorite(this.product.id,!this.isFav);this.isFav=!!state.favorite},
    async toggleFollow(){const state=await api.setFollow(this.product.shopId,!this.isFollow);this.isFollow=!!state.followed;this.product.fans=Number(state.fans||0)},goStore(){uni.reLaunch({url:'/pages/index/index'})},
    increaseQty(){if(this.qty>=10){uni.showToast({title:'单次最多购买10件',icon:'none'});return}this.qty++},
    submit(){if(!Number.isInteger(this.qty)||this.qty<1||this.qty>10){uni.showToast({title:'单次购买数量必须在1至10之间',icon:'none'});return}this.showSpec=false;uni.navigateTo({url:'/pages/order/submit?id='+this.product.id+'&sku='+this.selectedSku.id+'&qty='+this.qty})},
    async generatePoster(){if(this.posterBusy)return;this.posterBusy=true;uni.showLoading({title:'正在生成海报',mask:true});try{const poster=await api.createPoster(this.product.id);this.showShare=false;uni.navigateTo({url:'/pages/product/poster?id='+this.product.id+'&posterId='+poster.id})}catch(e){uni.showToast({title:e.message||'海报生成失败，请重试',icon:'none'})}finally{this.posterBusy=false;uni.hideLoading()}}
  }
}
</script>
<style scoped>
.detail-page{padding-bottom:150rpx}.main-image{width:100%;height:710rpx;background:#111}.product-main{display:flex;flex-direction:column;gap:12rpx}.product-name{font-size:32rpx;font-weight:700}.product-sub{color:var(--muted);font-size:25rpx}.price-line{display:flex;align-items:flex-end;justify-content:space-between}.big{font-size:42rpx}.actions{display:flex;gap:24rpx;color:var(--muted);font-size:23rpx}.actions>view{display:flex;align-items:center;gap:7rpx}.fav{color:var(--primary)}.spec-row{display:flex;align-items:center;justify-content:space-between}.spec-row>view{display:flex;flex-direction:column;gap:12rpx}.spec-text{color:var(--muted);font-size:24rpx}.details{display:flex;flex-direction:column;gap:18rpx;font-size:25rpx;line-height:42rpx}.warning{color:#f13e4b}.review-head{display:flex;justify-content:space-between}.review-list{margin-top:22rpx}.review-item{padding:20rpx 0;display:flex;flex-direction:column;gap:10rpx;border-bottom:1rpx solid var(--line);font-size:23rpx}.review-item>view{display:flex;justify-content:space-between;font-weight:700}.review-rating{color:var(--primary)}.review-item>.muted{font-size:20rpx}.review-empty{min-height:430rpx}.buybar{position:fixed;z-index:90;left:0;right:0;bottom:0;height:calc(116rpx + env(safe-area-inset-bottom));padding:14rpx 28rpx env(safe-area-inset-bottom);display:flex;gap:34rpx;background:var(--surface);border-top:1rpx solid var(--line)}.store{width:120rpx;flex-shrink:0;display:flex;flex-direction:column;align-items:center;justify-content:center}.store-label{font-size:22rpx;font-weight:400;line-height:1.5;white-space:nowrap}.buy{flex:1;height:80rpx}.sheet-mask{position:fixed;z-index:200;top:0;right:0;bottom:0;left:0;display:flex;align-items:flex-end;background:rgba(0,0,0,.55)}.sheet{width:100%;padding:28rpx 30rpx calc(28rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:var(--surface)}.sheet-top{display:flex;align-items:center;gap:20rpx;margin-bottom:32rpx}.sheet-top image{width:145rpx;height:145rpx;border-radius:14rpx}.sheet-top>view{flex:1;display:flex;flex-direction:column;gap:16rpx}.sheet-top>.close{flex:0 0 auto;align-self:flex-start;padding:8rpx}.sku-list{display:flex;flex-wrap:wrap;gap:16rpx;margin:22rpx 0 40rpx}.sku{padding:14rpx 24rpx;border:1rpx solid var(--line);border-radius:30rpx;background:var(--surface-soft);font-size:24rpx}.sku.active{border-color:var(--primary);color:var(--primary);background:var(--primary-soft)}.qty{display:flex;justify-content:space-between;align-items:center;margin-bottom:54rpx}.counter{display:flex}.counter>view,.counter>text{width:60rpx;height:52rpx;display:flex;align-items:center;justify-content:center;background:var(--surface-soft);border-right:4rpx solid var(--surface);font-size:26rpx}.share-sheet{width:100%;display:grid;grid-template-columns:1fr 1fr;padding:36rpx 60rpx 0;background:var(--surface);border-radius:26rpx 26rpx 0 0}.share-item{display:flex;flex-direction:column;align-items:center;gap:12rpx;color:var(--text);font-size:25rpx}.share-button{margin:0;padding:0;background:transparent;line-height:1.4}.share-icon{width:74rpx;height:74rpx;border-radius:50%;display:flex;align-items:center;justify-content:center}.blue{background:#3478ff}.green{background:#22c769}.cancel{grid-column:1/3;margin-top:36rpx;padding:28rpx;text-align:center;border-top:1rpx solid var(--line)}
</style>
